// Table-ownership guard.
//
// Generated tables carry a header line naming the script that produced them:
//
//   % auto-generated by scripts/gen-tables.mjs
//
// Two different scripts writing the same table path is a silent-corruption
// hazard: whichever runs last wins, and if the loser reads a superseded
// campaign the manuscript can end up citing stale numbers with a clean build.
// This check fails when a table name is written by more than one script, unless
// the pair is a declared producer/consumer pipeline.
//
// Run standalone (`node scripts/check-table-owners.mjs`) or via `make release-check`.
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const repo = path.resolve(root, "..");
const paperTables = path.join(repo, "paper", "tables");

// Declared pipelines: the orchestrator spawns the producer and then reads its
// output, so both legitimately name the same file. Key is the table, value the
// set of scripts allowed to share it.
const ALLOWED_SHARED = {
  "cv_all.tex": ["bench/analyze.mjs", "scripts/gen-analysis-tables.mjs"],
  // Producer/regenerator, not competing writers: canonicalization-cost.mjs runs
  // the host-sensitive microbenchmark and archives it; gen-canonicalization-table.mjs
  // rebuilds the same table from that archive without re-running the timing.
  "canonicalization_cost.tex": [
    "scripts/canonicalization-cost.mjs",
    "scripts/gen-canonicalization-table.mjs",
  ],
  // Not a contention: sync-tables.mjs names these only to EXCLUDE them, because they are
  // archive-only outputs that must never be copied into paper/tables. The detector is
  // deliberately broad and cannot tell an exclusion list from a write.
  "deepfetch_regimes.tex": ["scripts/gen-deepfetch-table.mjs", "scripts/sync-tables.mjs"],
  "analysis_roster.tex": ["scripts/sync-tables.mjs"],
  "cv_mysql.tex": ["bench/analyze.mjs", "scripts/gen-analysis-tables.mjs"],
  "resources_main.tex": ["bench/analyze.mjs", "scripts/gen-analysis-tables.mjs"],
};

const sources = [];
for (const dir of ["scripts", "bench"]) {
  const abs = path.join(root, dir);
  if (!fs.existsSync(abs)) continue;
  for (const name of fs.readdirSync(abs)) {
    if (!name.endsWith(".mjs")) continue;
    if (name === path.basename(import.meta.filename)) continue;
    sources.push({ rel: `${dir}/${name}`, text: fs.readFileSync(path.join(abs, name), "utf8") });
  }
}

// A script "writes" a table when it names the .tex file in a non-comment,
// non-logging line. Detection is deliberately broad: generators wrap writes in
// local helpers (writeBoth, writeResult), so matching only writeFile calls
// misses real contention. False positives are declared in ALLOWED_SHARED.
const writers = new Map();
const scopes = new Map();
for (const { rel, text } of sources) {
  for (const line of text.split("\n")) {
    const code = line.trim();
    if (code.startsWith("//") || code.startsWith("*") || code.includes("console.log")) continue;
    for (const match of code.matchAll(/['"]([A-Za-z0-9_.-]+\.tex)['"]/g)) {
      const table = match[1];
      if (!writers.has(table)) writers.set(table, new Set());
      writers.get(table).add(rel);
      const key = `${table}|${rel}`;
      const scope = scopes.get(key) ?? new Set();
      if (/paper/.test(code) || /writeBoth/.test(code)) scope.add("paper");
      if (/resultsDir|results/.test(code)) scope.add("results");
      scopes.set(key, scope);
    }
  }
}

const problems = [];
for (const [table, scripts] of [...writers].sort()) {
  if (scripts.size < 2) continue;
  const allowed = ALLOWED_SHARED[table];
  const list = [...scripts].sort();
  if (allowed && list.every((s) => allowed.includes(s))) continue;
  const header = (() => {
    const file = path.join(paperTables, table);
    if (!fs.existsSync(file)) return null;
    const first = fs.readFileSync(file, "utf8").split("\n", 1)[0];
    const m = first.match(/auto-generated by\s+(\S+)/);
    return m ? m[1].replace(/^experiments\//, "") : null;
  })();
  const scopeOf = Object.fromEntries(list.map((s) => [s, [...(scopes.get(`${table}|${s}`) ?? [])].sort().join('+')]));
  problems.push({ table, scripts: list, currentOwner: header, scopeOf });
}

if (problems.length === 0) {
  console.log(`table-owners: OK (${writers.size} generated tables, no contested owners)`);
  process.exit(0);
}
console.error(`table-owners: ${problems.length} table(s) written by more than one script.\n`);
for (const p of problems) {
  console.error(`  ${p.table}`);
  console.error(`    current owner (from header): ${p.currentOwner ?? "unknown / table not in paper/tables"}`);
  for (const s of p.scripts) {
    const tag = p.currentOwner && s === p.currentOwner ? "owner " : "OTHER ";
    console.error(`      ${tag} ${s}`);
  }
}
console.error(`
Whichever script runs last wins, so a stale writer can silently replace a table
built from the accepted campaign. Fix by giving the non-owner its own filename
and \\label, removing the superseded write, or - if this is a producer/consumer
pipeline - declaring it in ALLOWED_SHARED in scripts/check-table-owners.mjs.`);
process.exit(1);
